import{_ as o,o as t,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Version 2.0.0.3 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.3-released.md","filePath":"change-log/release/version-2.0.0.3-released.md"}'),n={name:"change-log/release/version-2.0.0.3-released.md"};function a(s,e,l,c,d,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="version-2-0-0-3-released" tabindex="-1">Version 2.0.0.3 Released <a class="header-anchor" href="#version-2-0-0-3-released" aria-label="Permalink to &quot;Version 2.0.0.3 Released&quot;">​</a></h1><h4 id="version-2-0-0-3-released-1" tabindex="-1">Version 2.0.0.3 Released <a class="header-anchor" href="#version-2-0-0-3-released-1" aria-label="Permalink to &quot;Version 2.0.0.3 Released&quot;">​</a></h4><p><strong>Date: 13th Apr 2026</strong></p><p><strong>Feature Release: Async-to-Sync WebSocket Migration, Market Price Protection (MPP), Samco 2FA, Shoonya OAuth, Multi-Device Session Tracking &amp; Security Hardening</strong></p><p>This is a feature release featuring <strong>59 commits</strong> (excluding auto-builds) from <strong>7 contributors</strong>, focused on migrating broker WebSocket adapters from asyncio to sync for Docker/eventlet compatibility, Market Price Protection (MPP) for Zerodha/Kotak/Samco/Tradejini, Samco 2FA authentication, Shoonya OAuth migration, multi-device session tracking, Telegram bot enhancements, and security hardening.</p><hr><p><strong>Highlights</strong></p><ul><li><strong>Async-to-Sync WebSocket Migration</strong> — Converted Zerodha, Upstox, and mstock streaming adapters from asyncio <code>websockets</code> to sync <code>websocket-client</code>, eliminating greenlet conflicts in Docker (Gunicorn + eventlet) deployments</li><li><strong>Market Price Protection (MPP)</strong> — Added automatic MARKET/SL-M to LIMIT/SL conversion with MPP for Zerodha, Kotak, Samco, and Tradejini, protecting traders from extreme price slippage</li><li><strong>Samco 2FA Authentication</strong> — Complete Samco 2FA implementation with OTP, secret key, IP management, and order status normalization</li><li><strong>Shoonya OAuth Migration</strong> — Migrated Shoonya from TOTP login to OAuth (GenAcsTok) authentication with WebSocket and SL-M MPP fixes</li><li><strong>Multi-Device Session Tracking</strong> — Session resume support across devices with active session monitoring and login activity tracking</li><li><strong>Telegram Bot Commands</strong> — New <code>/closeall</code> and <code>/mode</code> Telegram commands for remote position management and mode switching</li><li><strong>Dynamic Browser Tab Titles</strong> — All 80+ pages now show descriptive titles in browser tabs (e.g., &quot;OI Tracker | Tradeboard&quot;)</li><li><strong>Synthetic Future API Optimization</strong> — Reduced broker API calls from 4+ to 2 using multiquotes batching, cutting Dhan response time from ~8s to ~2s</li><li><strong>Multi-Arch Docker Images</strong> — CI/CD now builds both amd64 and arm64 Docker images on native runners</li><li><strong>Security Patches</strong> — Updated cryptography, axios, vite, Pygments, and lodash-es for CVE fixes</li></ul><hr><p><strong>New Features</strong></p><p><strong>Async-to-Sync WebSocket Migration</strong></p><ul><li>Convert Zerodha streaming from async websockets to sync websocket-client</li><li>Convert Upstox streaming from async websockets to sync websocket-client</li><li>Convert mstock streaming from async websockets to sync websocket-client</li><li>Reset Upstox and mstock reconnect counters on successful connection</li></ul><p><strong>Market Price Protection (MPP)</strong></p><ul><li>Enable market protection for Zerodha market orders with decimal strike preservation</li><li>Add MPP for Kotak market orders (MARKET → LIMIT, SL-M → SL with tick-based price protection)</li><li>Convert MARKET/SL-M orders to LIMIT/SL with MPP for Samco</li><li>Add MPP and fix orderbook status mapping for Tradejini</li><li>Guard <code>trigger_price</code> float conversion in SL-M MPP handler</li></ul><p><strong>Samco 2FA Authentication</strong></p><ul><li>Implement Samco 2FA authentication with OTP, secret key, and IP management</li><li>Refactor Samco 2FA to auth table with <code>aux_param</code> columns</li><li>Fix order status normalization for Cancel/Modify buttons in orderbook</li><li>Resolve FD leaks and resource issues in Samco WebSocket streaming</li><li>Use equity segment only for Samco funds to avoid double-counting</li></ul><p><strong>Shoonya OAuth Migration</strong></p><ul><li>Migrate Shoonya from TOTP login to OAuth (GenAcsTok) authentication</li><li>Fix Shoonya WebSocket, SL-M MPP conversion, and circular import</li><li>Fix review issues: input validation, null safety, log redaction</li></ul><p><strong>Multi-Device Session &amp; Login Activity</strong></p><ul><li>Multi-device session resume and active session tracking</li><li>Login activity tracking and security dashboard tabs</li><li>Resolve file descriptor and memory leak from uncleaned database sessions</li></ul><p><strong>Telegram Bot Enhancements</strong></p><ul><li>Add <code>/closeall</code> and <code>/mode</code> Telegram bot commands for remote trading control</li><li>Fix <code>/chart</code> rendering in Docker and eventlet environments</li></ul><p><strong>Frontend Enhancements</strong></p><ul><li>Dynamic browser tab titles for all 80+ pages (#881)</li><li>Copy and download buttons for Python strategy logs (#1233)</li><li>Add aria-labels to TradeBook buttons for accessibility (#1189)</li></ul><p><strong>Tradejini Broker Improvements</strong></p><ul><li>Add index symbol normalization and fix WebSocket exchange mapping</li><li>Prevent WebSocket FD leaks in quotes, depth, and streaming</li><li>Add MPP and fix orderbook status mapping</li></ul><p><strong>Smart Order Optimization</strong></p><ul><li>Remove 500ms smart order delay, add position cache + per-symbol lock for faster execution</li></ul><p><strong>Infrastructure</strong></p><ul><li>Build multi-arch Docker images (amd64 + arm64) on native runners</li><li>Replace <code>traceback.print_exc()</code> with <code>logger.exception()</code> across all REST API endpoints (#1012)</li></ul><hr><p><strong>Bug Fixes</strong></p><ul><li>Fix: prevent duplicate order execution race condition in sandbox mode</li><li>Fix: optimize synthetic future API — reduce broker API calls from 4+ to 2 using multiquotes (#855)</li><li>Fix: return mock response object instead of None for MPP ValueError</li><li>Fix: address cubic-dev P1 issues in order_api and auth_api</li><li>Fix: IIFL Capital index symbol normalization and quotes update</li><li>Fix: add IIFL Capital to install script files</li><li>Fix: add missing security headers to Flask responses (#1014)</li><li>Fix: standardize error logging with <code>logger.exception()</code> (#1017)</li><li>Fix: adjust font sizes and cell heights in seasonality heatmap</li><li>Fix: refine monthly data fetching and processing in seasonality</li><li>Fix: update tradeboard SDK to 1.0.47, remove numba/llvmlite dependencies</li></ul><hr><p><strong>Security</strong></p><ul><li>Bump cryptography to 46.0.7 (security patch)</li><li>Bump vite to 7.3.2 (security patch)</li><li>Bump axios to 1.15.0 (security patches)</li><li>Upgrade cryptography, Pygments, and lodash-es for security</li></ul><hr><p><strong>Contributors</strong></p><p>Special thanks to all contributors who made this release possible:</p><ul><li>@Kalaiviswa (kalaivani) — Async-to-sync WebSocket migration (Zerodha, Upstox, mstock), Tradejini MPP/FD fixes, Shoonya OAuth migration, Samco 2FA, multi-device session tracking</li><li>@marketcalls — Synthetic future optimization, browser tab titles, strategy log buttons, Telegram commands, smart order optimization, seasonality fixes</li><li>@Na1neeth (Navaneeth) — Samco 2FA authentication and WebSocket FD fixes</li><li>@Chessing234 (Taksh) — Security headers and error logging standardization</li><li>@LuckyAnsari22 — Database docstrings, TradeBook accessibility</li><li>@mvanhorn — Replace traceback.print_exc() with logger.exception()</li></ul><hr><p><strong>Links</strong></p><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li></ul><hr>',44)])])}const p=o(n,[["render",a]]);export{u as __pageData,p as default};
